        constexpr std::array<std::int32_t, SvAgentState::FieldCount>
            AgentStateFieldCodecs{
                -58, -100, -100, -57, -97, 16, -57, -100,
                10, 12, -97, -57, 32, 10, 10, 6,
                10, 6, 10, 6, 11, 11, 11, 6,
            };

        [[nodiscard]] bool validAgentState(const SvAgentState &state)
        {
            if (state.agentNum >= 24)
                return false;
            const SvAgentState nativeDefault{};
            for (std::size_t field{}; field < state.fields.size(); ++field)
            {
                const auto value = state.fields[field];
                const auto codec = AgentStateFieldCodecs[field];
                if (codec == -57 && value > 1)
                    return false;
                if (codec == -100 &&
                    !std::isfinite(std::bit_cast<float>(value)))
                {
                    return false;
                }
                if (codec > 0 && codec < 32 &&
                    value != SvAgentState{}.fields[field] &&
                    value >= (1u << codec))
                {
                    return false;
                }
            }
            return true;
        }

        [[nodiscard]] std::uint16_t actorTorsoAnimation(
            const SvAgentState &agent)
        {
            switch (agent.fields[SvAgentState::AttachmentField])
            {
            case 264: return agent.fields[12] == 7 ? 1204 : 1202;
            case 289: return 1206;
            case 463: return 1192;
            case 466: return 1195;
            case 479: return 1208;
            case 480: return 1209;
            case 481: return 1210;
            case 482: return 1211;
            case 484: return 1213;
            default: return 0;
            }
        }

