    bool SvServerWorld::setPlayerTouchHandler(
        const std::uint32_t clientNum,
        SvEntityTouchHandler handler)
    {
        if (clientNum >= MaximumGameClients ||
            !clientStates_.contains(clientNum))
        {
            return false;
        }
        if (!handler)
        {
            playerTouchHandlers_.erase(clientNum);
            return true;
        }
        playerTouchHandlers_.insert_or_assign(clientNum, std::move(handler));
        return true;
    }

    bool SvServerWorld::setEntityTouchHandler(
        const SvEntityHandle handle,
        SvEntityTouchHandler handler)
    {
        if (!entityPool_ || !entityPool_->resolve(handle) ||
            !entities_.contains(handle.entityNum))
        {
            return false;
        }
        if (!handler)
        {
            entityTouchHandlers_.erase(handle.entityNum);
            return true;
        }
        entityTouchHandlers_.insert_or_assign(handle.entityNum, DynamicEntityTouchHandler{
            .generation = handle.generation,
            .handler = std::move(handler),
        });
        return true;
    }

    bool SvServerWorld::setEntityDamageState(
        const SvEntityHandle handle,
        const std::optional<SvEntityDamageState> state)
    {
        if (!entityPool_ || !entityPool_->resolve(handle) ||
            !entities_.contains(handle.entityNum))
        {
            return false;
        }
        if (!state)
        {
            entityDamageStates_.erase(handle.entityNum);
            entityDamageHandlers_.erase(handle.entityNum);
            return true;
        }
        if (!SV_IsEntityDamageStateValid(*state))
            return false;
        entityDamageStates_.insert_or_assign(handle.entityNum, *state);
        if(zmDeathFx_.bo1Derived)
            if(auto fx=zmDeathFxStates_.find(handle.entityNum);fx!=zmDeathFxStates_.end())
                fx->second.maxHealth=std::max(fx->second.maxHealth,state->health);
        return true;
    }

    std::optional<SvEntityDamageState> SvServerWorld::entityDamageState(
        const SvEntityHandle handle) const
    {
        if (!entityPool_ || !entityPool_->resolve(handle) ||
            !entities_.contains(handle.entityNum))
        {
            return std::nullopt;
        }
        const auto state = entityDamageStates_.find(handle.entityNum);
        return state != entityDamageStates_.end()
            ? std::optional{ state->second }
            : std::nullopt;
    }

    std::optional<SvEntityDamageRuntimeStatus>
        SvServerWorld::entityDamageRuntimeStatus(
            const std::uint32_t entityNum) const
    {
        const auto *const lifetime = entityPool_
            ? entityPool_->resolve(entityNum)
            : nullptr;
        const auto entity = entities_.find(entityNum);
        const auto state = entityDamageStates_.find(entityNum);
        if (!lifetime || entity == entities_.end() ||
            state == entityDamageStates_.end())
        {
            return std::nullopt;
        }
        return SvEntityDamageRuntimeStatus{
            .entityNum = entityNum,
            .generation = lifetime->generation,
            .state = state->second,
            .modelIndex = entity->second.networkState.modelIndex,
        };
    }

    bool SvServerWorld::setEntityDamageHandler(
        const SvEntityHandle handle,
        SvEntityDamageHandler handler)
    {
        if (!entityPool_ || !entityPool_->resolve(handle) || !handler ||
            !entityDamageStates_.contains(handle.entityNum))
        {
            return false;
        }
        entityDamageHandlers_.insert_or_assign(
            handle.entityNum,
            DynamicEntityDamageHandler{
                .generation = handle.generation,
                .handler = std::move(handler),
            });
        return true;
    }

    bool SvServerWorld::configureEntityDamageOwner(
        const SvEntityHandle handle,
        const SvEntityDamageState state,
        SvEntityDamageHandler handler)
    {
        if (!entityPool_ || !entityPool_->resolve(handle) ||
            !entities_.contains(handle.entityNum) ||
            !SV_IsEntityDamageStateValid(state) || !handler)
        {
            return false;
        }
        entityDamageStates_.insert_or_assign(handle.entityNum, state);
        entityDamageHandlers_.insert_or_assign(
            handle.entityNum,
            DynamicEntityDamageHandler{
                .generation = handle.generation,
                .handler = std::move(handler),
            });
        return true;
    }

