    std::optional<SvEntityHandle> SvServerWorld::spawnScriptModel(
        const std::uint16_t modelIndex,
        const std::string_view modelName,
        const std::array<float, 3> &origin,
        const std::array<float, 3> &angles)
    {
        const auto finiteVector = [](const auto &vector) {
            return std::ranges::all_of(vector, [](const float value) {
                return std::isfinite(value);
            });
        };
        // The same argument screen setScriptModelPresentation applies, run BEFORE a
        // slot is taken rather than after: a rejected spawn must not cost an entity.
        // `*` prefixes name a brush model, which is not an xModel and cannot be
        // attached this way.
        if (!modelIndex || modelIndex >= ModelConfigStringCount ||
            modelName.empty() || modelName.front() == '*' ||
            modelName.find('\0') != std::string_view::npos ||
            !finiteVector(origin) || !finiteVector(angles))
        {
            return std::nullopt;
        }
        const auto handle = spawnEntity();
        if (!handle)
            return std::nullopt;
        const auto slot = entities_.find(handle->entityNum);
        if (slot == entities_.end())
        {
            (void)freeEntity(*handle);
            return std::nullopt;
        }

        auto &entity = slot->second;
        entity.networkState.number = handle->entityNum;
        entity.networkState.eType = EntityTypeScriptMover;
        entity.networkState.origin = origin;
        entity.networkState.angles = angles;
        entity.networkState.modelIndex = modelIndex;
        entity.networkState.modelScale = 1.0f;
        entity.clientNum = EntityNumNone;
        entity.currentOrigin = origin;
        entity.currentAngles = angles;
        entity.scriptModelName.assign(modelName);
        // "script_model" so getentarray's classname key finds these alongside the
        // map's own, which is how a script re-discovers loot it did not keep a
        // reference to.
        entity.mapClassName = "script_model";
        // See the header: scenery. A zero-bounds capsule is in no trace at all.
        entity.collisionShape = SvCollisionShape::Capsule;
        entity.collisionBounds = {};
        entity.collisionLinked = false;
        // THE TWO LINES THAT DECIDE WHETHER ANY OF THIS IS VISIBLE. The publication
        // gate is `if (!entity.gameplayActive) return false;`, and mapModeEligible is
        // what setScriptModelPresentation later checks before it will activate this
        // entity -- without it every subsequent setmodelat on this loot would fail the
        // same way the original spawn did.
        entity.gameplayActive = true;
        entity.mapModeEligible = true;
        return handle;
    }

    void SvServerWorld::setZmNavGraph(SvZmNavGraph graph)
    {
        zmNavGraph_ = std::move(graph);
        actorRoutes_.clear();

        // LABEL EVERY NODE WITH ITS CONNECTED COMPONENT, once, here.
        //
        // Weak topology membership only: A* additionally enforces barrier direction
        // and live blocked edges. Membership does not prove a route. The largest component is taken as the map's main
        // body: on factory that is 837 of 1100 nodes and it is where the players'
        // own nearest node lands.
        const auto nodeCount = zmNavGraph_.nodes.size();
        zmNavComponent_.assign(nodeCount, 0u);
        zmNavMainComponent_ = 0u;
        if (nodeCount == 0)
            return;
        std::vector<bool> seen(nodeCount, false);
        std::vector<std::uint16_t> stack;
        std::uint16_t component = 0;
        std::size_t largest = 0;
        for (std::size_t start = 0; start < nodeCount; ++start)
        {
            if (seen[start])
                continue;
            std::size_t size = 0;
            stack.clear();
            stack.push_back(static_cast<std::uint16_t>(start));
            seen[start] = true;
            while (!stack.empty())
            {
                const auto node = stack.back();
                stack.pop_back();
                zmNavComponent_[node] = component;
                ++size;
                for (const auto neighbour : zmNavGraph_.neighbours(node))
                {
                    if (seen[neighbour])
                        continue;
                    seen[neighbour] = true;
                    stack.push_back(neighbour);
                }
            }
            if (size > largest)
            {
                largest = size;
                zmNavMainComponent_ = component;
            }
            ++component;
        }
        OlMod::RuntimeLog::write(
            OlMod::RuntimeLog::Channel::GameServer,
            "zm navgraph components nodes=" + std::to_string(nodeCount) +
            " components=" + std::to_string(component) +
            " main=" + std::to_string(zmNavMainComponent_) +
            " mainNodes=" + std::to_string(largest));
    }

    bool SvServerWorld::zmGoalRoutable(const std::array<float, 3> &goal) const
    {
        // The SAME radius the router uses to turn a goal into a node. A goal that
        // does not land on a node has no way on to the graph at all, which is the
        // other half of unroutable.
        const auto node = SV_ZmNavNearestNode(zmNavGraph_, goal, 64.0f);
        if (!node || *node >= zmNavComponent_.size())
            return false;
        return zmNavComponent_[*node] == zmNavMainComponent_;
    }

    bool SvServerWorld::zmSpawnCrossesBarrier(
        const std::array<float, 3> &goal) const
    {
        // OLMOD(window-spawn-eligibility): align selection with map/demo-owned entrance.
        // Eligibility must honor the same entrance ownership as stepZombieActors.
        // In particular auto414 is explicitly mapped to pf683 from retail demo
        // evidence. A plain shortest path can bypass that entrance and formerly
        // excluded its spawner before the actor controller ever ran.
        const auto measured = zmNavGraph_.spawnBarrierByGoal.find(goal);
        if (measured != zmNavGraph_.spawnBarrierByGoal.end())
            return zmBarriers_.contains(measured->second) && zmGoalRoutable(goal);
        constexpr float MaximumGoalToBarrierDistanceSquared = 128.0f * 128.0f;
        for (const auto &[edge, barrier] : zmBarriers_)
        {
            const auto &outside = zmNavGraph_.nodes[barrier.outsideNode];
            const auto dx = outside[0] - goal[0];
            const auto dy = outside[1] - goal[1];
            const auto dz = outside[2] - goal[2];
            if (dx * dx + dy * dy + dz * dz <= MaximumGoalToBarrierDistanceSquared)
                return zmGoalRoutable(goal);
        }
        const auto start = SV_ZmNavNearestNode(zmNavGraph_, goal, 64.0f);
        if (!start)
            return false;
        // The same destination the router picks, measured from the SPAWN POINT
        // rather than from an actor, because no actor exists yet.
        const auto destination = nearestPlayerNavNode(goal);
        if (!destination)
            return false;
        const auto route = SV_ZmNavRoute(zmNavGraph_, *start, *destination);
        for (std::size_t leg = 1; leg < route.size(); ++leg)
        {
            // Barriers are keyed by the node pair of their traversal and the graph
            // is undirected, so both orderings have to be tried.
            const auto from = route[leg - 1];
            const auto to = route[leg];
            if (zmBarriers_.contains({ from, to }) ||
                zmBarriers_.contains({ to, from }))
            {
                return true;
            }
        }
        return false;
    }

