    bool SvServerWorld::clearPlayerRewardState(
        const std::uint32_t clientNum)
    {
        const auto client = clientStates_.find(clientNum);
        if (client == clientStates_.end())
            return false;
        auto &state = client->second.client.playerState;
        state.killstreak = 0;
        state.setRewardSlots({}, {});
        state.rewardActionType = 0;
        state.rewardActionWeapon = 0;
        return true;
    }

    bool SvServerWorld::setPlayerEquippedRewards(const std::uint32_t clientNum,
        const std::array<std::uint8_t, 3> &ids,
        const std::array<std::uint8_t, 3> &targets)
    {
        const auto client = clientStates_.find(clientNum);
        if (client == clientStates_.end() ||
            std::ranges::any_of(targets, [](auto value) { return value > 31; }))
            return false;
        auto &state = client->second.client.playerState;
        auto allIds = state.rewardIds();
        auto allTargets = state.rewardTargets();
        // CODREF(1649370): demo @43100 IDs fields127..129, targets132..134.
        // Three equipped slots are runtime 1..3; slots 0/4 have
        // separate owners and must not be overwritten by a loadout refresh.
        std::copy(ids.begin(), ids.end(), allIds.begin() + 1);
        std::copy(targets.begin(), targets.end(), allTargets.begin() + 1);
        state.setRewardSlots(allIds, allTargets);
        return true;
    }

